Given an array arr[] of non-negative integers, where each element represents the maximum number of steps you can jump forward from that index, determine the minimum number of jumps required to reach the last index starting from the first index. If it is not possible to reach the end, return -1.Examples: Input: arr[] = [1, 3, 5, 8, 9, 2, 6, 7, 6, 8, 9]Output: 3 Explanation: First jump from 1st element to 2nd element with value 3. From here we jump to 5th element with value 9, and from here we will jump to the last. Input: arr []= [1, 4, 3, 2, 6, 7]Output: 2 Explanation: First we jump from the 1st to 2nd element and then jump to the last element.Input: arr[] = [0, 10, 20]Output: -1Explanation: We cannot go anywhere from the 1st element.Try It YourselfTable of Content[Naive  Approach] Using Recursion - O(n^n) Time and O(n) Space[Better Approach] Using Bottom-Up DP (Tabulation) - O(n^2) Time and O(n) Space[Expected Approach] Using Greedy Approach - O(n) Time and O(1) Space[Naive  Approach] Using Recursion - O(n^n) Time and O(n) SpaceRecursively try all possible jumps from each index. From position i, we can jump to any index between i + 1 and i + arr[i], and for each of these, we compute the minimum jumps needed to reach the end. then take the minimum among those and add 1 for the current jump. Basically minJumps(i) = 1 + min(minJumps(k)) for all valid k reachable from i.
            C++

    #include <iostream>
#include <vector>
#include <climits>
using namespace std;

// Returns minimum jumps needed from index i to reach end
int minJumpsRecur(int i, vector<int> &arr) {
    if (i >= arr.size() - 1)
        return 0;

    int ans = INT_MAX;

    // Try all reachable positions from i
    for (int j = i + 1; j <= i + arr[i]; j++) {
        int val = minJumpsRecur(j, arr);
        if (val != INT_MAX)
            ans = min(ans, 1 + val);
    }

    return ans;
}

int minJumps(vector<int>& arr) {
    int ans = minJumpsRecur(0, arr);
    return (ans == INT_MAX) ? -1 : ans; 
}

int main() {
    vector<int> arr = {1, 3, 5, 8, 9, 2, 6, 7, 6, 8, 9};
    cout << minJumps(arr);
    return 0;
}


