Output3[Expected Approach] Using Greedy Approach - O(n) Time and O(1) SpaceThe core idea is to greedily track the farthest reachable index (maxReach).  Instead of jumping at every step, keep moving within the current range. Only when you reach the end of that range, take a jump and extend the range to maxReach. This way, each jump covers the maximum possible distance, ensuring the minimum number of jumps.For implementation, these variables are utilized during the iterative process:jumps: Tracks the total jumps made.currentReach: Represents the boundary of the current jump.maxReach: Stores the furthest reachable index.In each iteration, update maxReach as max(maxReach, i + arr[i]). When currentReach is reached, increase jumps and set currentReach to maxReach. If at any time i equals currentReach and maxReach is also equal to currentReach, it's impossible to reach the end, thus return -1.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int minJumps(vector<int> &arr){
    int n = arr.size();

    if (arr[0] == 0)
        return -1;

    int maxReach = 0;
    int currReach = 0;
    int jump = 0;

    for (int i = 0; i < n; i++){
        maxReach = max(maxReach, i + arr[i]);
        if (maxReach >= n - 1){
            return jump + 1;
        }

        // Increment the Jump as we reached the
        // Current Reachable index
        if (i == currReach){

            // If Max reach is same as current index
            // then we can not jump further
            if (maxReach == i){
                return -1;
            }

            // If maxReach > current index then increment
            // jump and update current reachable index
            else{
                jump++;
                currReach = maxReach;
            }
        }
    }

    return -1;
}

int main()
{
   vector<int> arr = {1, 3, 5, 8, 9, 2, 6, 7, 6, 8, 9};
    cout << minJumps(arr);
    return 0;
}


